const input = $input.first().json;

let payload = input.body ?? input;

if (typeof payload === 'string') {
  try {
    payload = JSON.parse(payload);
  } catch {
    throw new Error(
      'Webhook-Body ist kein gültiges JSON.'
    );
  }
}

const docUrl = payload?.doc_url;

if (
  typeof docUrl !== 'string' ||
  !docUrl.trim()
) {
  throw new Error(
    'Webhook-Feld "doc_url" fehlt. ' +
    'Paperless muss Name=doc_url und Wert={{doc_url}} senden.'
  );
}

const match = docUrl.match(
  /\/documents\/(\d+)\/?/
);

if (!match) {
  throw new Error(
    `Dokument-ID wurde in doc_url nicht gefunden: ${docUrl}`
  );
}

return [{
  json: {
    ...payload,
    doc_url: docUrl,
    document_id: Number(match[1]),
  },
}];

const document =
  $('Dokumentdaten und Datei zusammenführen').first().json;

return $input.all().map((item, index) => {
  const fileName =
    item.binary?.data?.fileName ??
    `page-${index + 1}.png`;

  const match = fileName.match(/page-(\d+)\.png$/i);

  return {
    json: {
      document_id: document.id,
      title: document.title ?? '',
      original_file_name:
        document.original_file_name ??
        document.filename ??
        '',

      original_content:
        document.content ?? '',

      original_custom_fields:
        Array.isArray(document.custom_fields)
          ? document.custom_fields
          : [],

      page_number:
        match
          ? Number(match[1])
          : index + 1,

      page_file_name: fileName,
    },

    binary: item.binary,
  };
});

const page =
  $('Seiten einzeln verarbeiten').item.json;

return {
  json: {
    ...page,
    image_base64: $json.image_base64,
  },
};

/**
 * Extrahiert einzelne vollständige JSON-Objekte.
 */
function extractJsonObjects(text) {
  const results = [];

  let start = -1;
  let depth = 0;
  let inString = false;
  let escaped = false;

  for (let index = 0; index < text.length; index++) {
    const char = text[index];

    if (inString) {
      if (escaped) {
        escaped = false;
        continue;
      }

      if (char === '\\') {
        escaped = true;
        continue;
      }

      if (char === '"') {
        inString = false;
      }

      continue;
    }

    if (char === '"') {
      inString = true;
      continue;
    }

    if (char === '{') {
      if (depth === 0) {
        start = index;
      }

      depth++;
      continue;
    }

    if (char === '}') {
      depth--;

      if (
        depth === 0 &&
        start >= 0
      ) {
        results.push(
          text.slice(
            start,
            index + 1
          )
        );

        start = -1;
      }
    }
  }

  return results;
}

/**
 * Repariert ungültige Backslashes in Modellantworten.
 */
function repairInvalidJsonEscapes(value) {
  return value.replace(
    /\\(?!["\\/bfnrtu])/g,
    '\\\\'
  );
}

function parseModelResult(value) {
  const raw =
    String(value ?? '').trim();

  const cleaned = raw
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/\s*```$/i, '')
    .trim();

  const candidates = [];

  /*
   * Zuerst jeden einzelnen Markdown-Codeblock prüfen.
   * So wird bei mehrfach ausgegebenem JSON nur ein Block
   * verwendet.
   */
  const fencedPattern =
    /```(?:json)?\s*([\s\S]*?)```/gi;

  for (
    const match of raw.matchAll(
      fencedPattern
    )
  ) {
    if (match[1]?.trim()) {
      candidates.push(
        match[1].trim()
      );
    }
  }

  /*
   * Danach einzelne vollständige JSON-Objekte suchen.
   */
  candidates.push(
    ...extractJsonObjects(cleaned)
  );

  /*
   * Zum Schluss den gesamten bereinigten Inhalt prüfen.
   */
  candidates.push(cleaned);

  const checked = new Set();

  for (const candidate of candidates) {
    const trimmed =
      String(candidate ?? '').trim();

    if (
      !trimmed ||
      checked.has(trimmed)
    ) {
      continue;
    }

    checked.add(trimmed);

    const variants = [
      trimmed,
      repairInvalidJsonEscapes(trimmed),
    ];

    for (const variant of variants) {
      try {
        const parsed =
          JSON.parse(variant);

        return {
          parsed: true,
          data: parsed,
        };
      } catch {
        // Nächste Variante prüfen.
      }
    }
  }

  return {
    parsed: false,
    data: {},
  };
}

const pageInput =
  $('Base64-Metadaten ergänzen').item.json;

const isFirstPage =
  Number(pageInput.page_number) === 1;

const ai =
  parseModelResult(
    $json.message?.content
  );

return {
  json: {
    document_id:
      pageInput.document_id,

    title:
      pageInput.title,

    original_file_name:
      pageInput.original_file_name,

    original_content:
      isFirstPage
        ? pageInput.original_content
        : '',

    original_custom_fields:
      isFirstPage
        ? pageInput.original_custom_fields
        : [],

    page_number:
      pageInput.page_number,

    page_file_name:
      pageInput.page_file_name,

    ai_parsed:
      ai.parsed,

    ai:
      ai.data,
  },
};

const pages = $input
  .all()
  .map(item => item.json)
  .sort(
    (a, b) =>
      Number(a.page_number) -
      Number(b.page_number)
  );

function toArray(value) {
  if (!Array.isArray(value)) {
    return [];
  }

  return value.filter(item =>
    item !== null &&
    item !== undefined &&
    (
      typeof item !== 'string' ||
      item.trim() !== ''
    )
  );
}

function extractOriginalPaperlessContent(content) {
  const value =
    String(content ?? '').trim();

  const marker =
    '=== Ursprünglicher Paperless-OCR-Inhalt ===';

  if (!value.includes(marker)) {
    return value;
  }

  return value
    .split(marker)
    .slice(1)
    .join(marker)
    .trim();
}

const symbolNames = {
  '❤️': 'Herz',
  '❤': 'Herz',
  '♥': 'Herz',
  '♡': 'Herz',
  '△': 'Dreieck',
  '▲': 'Dreieck',
  '▽': 'Dreieck',
  '▼': 'Dreieck',
  '□': 'Quadrat',
  '■': 'Quadrat',
  '☒': 'Quadrat mit Kreuz',
  '⊠': 'Quadrat mit Kreuz',
  '○': 'Kreis',
  '◯': 'Kreis',
  '●': 'Kreis',
  '×': 'Kreuz',
  '✕': 'Kreuz',
  '✖': 'Kreuz',
  '✓': 'Häkchen',
  '✔': 'Häkchen',
  '→': 'Pfeil nach rechts',
  '←': 'Pfeil nach links',
  '↑': 'Pfeil nach oben',
  '↓': 'Pfeil nach unten',
};

function formatSymbol(value) {
  if (!value || typeof value !== 'object') {
    return null;
  }

  const symbol =
    String(value.symbol ?? '').trim();

  const label =
    String(value.label ?? '').trim() ||
    symbolNames[symbol] ||
    '';

  if (!label && !symbol) {
    return null;
  }

  if (label && symbol) {
    return `${label} (Symbol: ${symbol})`;
  }

  return label || symbol;
}

function formatCheckbox(value) {
  if (!value || typeof value !== 'object') {
    return null;
  }

  const label =
    String(value.label ?? '').trim() ||
    'Kontrollkästchen';

  const stateNames = {
    checked: 'angekreuzt',
    unchecked: 'nicht angekreuzt',
    unclear: 'Status unklar',
  };

  const state =
    stateNames[value.state] ??
    'Status unklar';

  return `${label} (Kontrollkästchen: ${state})`;
}

function formatVisualElement(value) {
  if (!value || typeof value !== 'object') {
    return null;
  }

  const typeNames = {
    logo: 'Logo',
    stamp: 'Stempel',
    signature: 'Unterschrift',
    image: 'Bild',
    figure: 'Abbildung',
    marking: 'Markierung',
    other: 'visuelles Element',
  };

  const label =
    String(value.label ?? '').trim();

  if (!label) {
    return null;
  }

  const type =
    typeNames[value.type] ??
    typeNames.other;

  return `${label} (${type})`;
}

const contentParts = [];
const visualParts = [];
const warnings = [];
let markdownTableDetected = false;

for (const page of pages) {
  const ai =
    page.ai ?? {};

  const content =
    String(
      ai.content_markdown ?? ''
    ).trim();

  if (content) {
    contentParts.push(
      `## Seite ${page.page_number}\n\n${content}`
    );

    if (
      /^\s*\|.+\|\s*$/m.test(content) &&
      /^\s*\|(?:\s*:?-+:?\s*\|)+\s*$/m.test(content)
    ) {
      markdownTableDetected = true;
    }
  }

  const pageVisuals = [];

  for (
    const value of toArray(ai.symbols)
  ) {
    const formatted =
      formatSymbol(value);

    if (formatted) {
      pageVisuals.push(formatted);
    }
  }

  for (
    const value of toArray(ai.checkboxes)
  ) {
    const formatted =
      formatCheckbox(value);

    if (formatted) {
      pageVisuals.push(formatted);
    }
  }

  for (
    const value of toArray(
      ai.visual_elements
    )
  ) {
    const formatted =
      formatVisualElement(value);

    if (formatted) {
      pageVisuals.push(formatted);
    }
  }

  if (pageVisuals.length > 0) {
    visualParts.push(
      `## Seite ${page.page_number}\n\n` +
      pageVisuals
        .map(value => `- ${value}`)
        .join('\n')
    );
  }

  for (
    const warning of toArray(ai.warnings)
  ) {
    warnings.push(
      `Seite ${page.page_number}: ${warning}`
    );
  }

  if (page.ai_parsed !== true) {
    warnings.push(
      `Seite ${page.page_number}: KI-Antwort konnte nicht als JSON verarbeitet werden`
    );
  }
}

const aiSections = [];

if (contentParts.length > 0) {
  aiSections.push(
    `# Dokumentinhalt\n\n` +
    contentParts.join('\n\n')
  );
}

if (visualParts.length > 0) {
  aiSections.push(
    `# Suchrelevante visuelle Elemente\n\n` +
    visualParts.join('\n\n')
  );
}

const aiContent =
  aiSections
    .join('\n\n')
    .trim();

const originalPaperlessContent =
  extractOriginalPaperlessContent(
    pages[0]?.original_content
  );

const originalSection =
  originalPaperlessContent ||
  '[Kein ursprünglicher Paperless-OCR-Inhalt vorhanden]';

const combinedPaperlessContent = [
  '=== KI-OCR / Vision-Ergebnis ===',
  '',
  aiContent ||
    '[Kein brauchbares KI-OCR-Ergebnis erzeugt]',
  '',
  '=== Ursprünglicher Paperless-OCR-Inhalt ===',
  '',
  originalSection,
]
  .join('\n')
  .trim();

const normalizedAiContent =
  aiContent.toLowerCase();

const contentWithoutErrorPhrases =
  normalizedAiContent
    .replace(/\[?unlesbar\]?/gi, '')
    .replace(/keine daten/gi, '')
    .replace(/nicht erkennbar/gi, '')
    .replace(/kein text erkannt/gi, '')
    .replace(/^#+.*$/gm, '')
    .replace(/\s+/g, '');

const quality = {
  usable:
    pages.length > 0 &&
    pages.every(
      page => page.ai_parsed === true
    ) &&
    aiContent.length >= 100 &&
    contentWithoutErrorPhrases.length >= 30,

  ai_character_count:
    aiContent.length,

  original_character_count:
    originalPaperlessContent.length,

  combined_character_count:
    combinedPaperlessContent.length,

  page_count:
    pages.length,

  ai_json_valid_for_all_pages:
    pages.length > 0 &&
    pages.every(
      page => page.ai_parsed === true
    ),

  markdown_table_detected:
    markdownTableDetected,

  visual_descriptions_present:
    visualParts.length > 0,

  warnings,
};

return [
  {
    json: {
      document_id:
        pages[0]?.document_id,

      title:
        pages[0]?.title ?? '',

      original_file_name:
        pages[0]?.original_file_name ?? '',

      original_custom_fields:
        pages[0]?.original_custom_fields ?? [],

      ai_content:
        aiContent,

      original_paperless_content:
        originalPaperlessContent,

      combined_paperless_content:
        combinedPaperlessContent,

      quality,

      write_back: true,
    },
  },
];

const fieldId = 0;

const customFields =
  Array.isArray($json.custom_fields)
    ? $json.custom_fields
    : [];

const processedField =
  customFields.find(
    field => Number(field.field) === fieldId
  );

return {
  json: {
    ...$json,
    ki_ocr_processed:
      processedField?.value === true,
  },
};

const FIELD_IDS = {
  'KI-OCR verarbeitet': 0,
  Betroffener: 0,
  Rechnungsbetrag: 0,
  Bezahlt: 0,
  'Frist - Wiedervorlage': 0,
  Fortbildung: 0,
  'Leistungszeitraum von': 0,
  'Leistungszeitraum bis': 0,
  Rechnungsnummer: 0,
};

const OVERWRITE_EXISTING = false;

const requiredNames = [
  'KI-OCR verarbeitet',
  'Betroffener',
  'Rechnungsbetrag',
  'Bezahlt',
  'Frist - Wiedervorlage',
  'Fortbildung',
  'Leistungszeitraum von',
  'Leistungszeitraum bis',
  'Rechnungsnummer',
];

const invalidConfiguration =
  requiredNames.filter(
    name =>
      !Number.isInteger(
        Number(FIELD_IDS[name])
      ) ||
      Number(FIELD_IDS[name]) <= 0
  );

if (invalidConfiguration.length > 0) {
  throw new Error(
    'Paperless-Feld-IDs fehlen oder sind ungültig: ' +
    invalidConfiguration.join(', ')
  );
}

const existing =
  Array.isArray(
    $json.original_custom_fields
  )
    ? $json.original_custom_fields.map(
        item => ({ ...item })
      )
    : [];

const detected =
  Array.isArray(
    $json.detected_custom_fields
  )
    ? $json.detected_custom_fields
    : [];

function hasMeaningfulValue(value) {
  if (
    value === null ||
    value === undefined
  ) {
    return false;
  }

  if (
    typeof value === 'string' &&
    value.trim() === ''
  ) {
    return false;
  }

  if (
    Array.isArray(value) &&
    value.length === 0
  ) {
    return false;
  }

  return true;
}

const report = {
  recognized:
    detected.length,

  added:
    [],

  filled_empty:
    [],

  preserved_existing:
    [],

  ignored_unknown:
    [],
};

for (const item of detected) {
  const fieldName =
    String(item?.name ?? '').trim();

  const fieldId =
    Number(FIELD_IDS[fieldName]);

  if (
    !fieldName ||
    !Number.isInteger(fieldId) ||
    fieldId <= 0
  ) {
    report.ignored_unknown.push(
      fieldName || '[ohne Feldname]'
    );
    continue;
  }

  const existingIndex =
    existing.findIndex(
      entry =>
        Number(entry.field) === fieldId
    );

  if (existingIndex >= 0) {
    const existingValue =
      existing[existingIndex].value;

    if (
      hasMeaningfulValue(existingValue) &&
      !OVERWRITE_EXISTING
    ) {
      report.preserved_existing.push(
        fieldName
      );
      continue;
    }

    existing[existingIndex] = {
      ...existing[existingIndex],
      field:
        fieldId,
      value:
        item.value,
    };

    report.filled_empty.push(
      fieldName
    );
    continue;
  }

  existing.push({
    field:
      fieldId,
    value:
      item.value,
  });

  report.added.push(fieldName);
}

const statusFieldId =
  Number(
    FIELD_IDS['KI-OCR verarbeitet']
  );

const statusIndex =
  existing.findIndex(
    entry =>
      Number(entry.field) ===
      statusFieldId
  );

if (statusIndex >= 0) {
  existing[statusIndex] = {
    ...existing[statusIndex],
    field:
      statusFieldId,
    value:
      true,
  };
} else {
  existing.push({
    field:
      statusFieldId,
    value:
      true,
  });
}

return {
  json: {
    ...$json,

    updated_custom_fields:
      existing,

    custom_field_update_report:
      report,
  },
};

