const input = $input.first().json;

const aiContent =
  String(input.ai_content ?? '').trim();

if (!aiContent) {
  throw new Error(
    'ai_content fehlt. Die Felderkennung darf nur den von unserer KI erzeugten Inhalt verwenden.'
  );
}

if (
  aiContent.includes(
    '=== Ursprünglicher Paperless-OCR-Inhalt ==='
  )
) {
  throw new Error(
    'Der ursprüngliche Paperless-OCR-Inhalt wurde unerwartet an die Felderkennung übergeben.'
  );
}

const MAX_SOURCE_CHARACTERS = 12000;
const DOCUMENT_BEGINNING_CHARACTERS = 2500;
const CONTEXT_LINES_BEFORE = 2;
const CONTEXT_LINES_AFTER = 3;

function normalizeSearchText(value) {
  return String(value ?? '')
    .toLowerCase()
    .replace(/ä/g, 'ae')
    .replace(/ö/g, 'oe')
    .replace(/ü/g, 'ue')
    .replace(/ß/g, 'ss')
