const selectedIndexes = new Set();
const matchedFields = new Set();
const matchedAliases = new Set();

function addIndex(index) {
  if (
    index >= 0 &&
    index < lines.length
  ) {
    selectedIndexes.add(index);
  }
}

function addWindow(
  index,
  before = CONTEXT_LINES_BEFORE,
  after = CONTEXT_LINES_AFTER
) {
  for (
    let current = index - before;
    current <= index + after;
    current++
  ) {
    addIndex(current);
  }
}

function addCompleteTable(index) {
  if (!lines[index]?.trim().startsWith('|')) {
    return;
  }

  let start = index;
  let end = index;

  while (
    start > 0 &&
    lines[start - 1].trim().startsWith('|')
  ) {
    start--;
  }

  while (
    end + 1 < lines.length &&
    lines[end + 1].trim().startsWith('|')
  ) {
    end++;
  }

  for (
    let current = start;
    current <= end;
    current++
  ) {
    addIndex(current);
  }
}

let beginningCharacters = 0;

for (
  let index = 0;
  index < lines.length;
  index++
) {
  if (
    beginningCharacters >=
    DOCUMENT_BEGINNING_CHARACTERS
  ) {
    break;
  }

  addIndex(index);
  beginningCharacters +=
    lines[index].length + 1;
}

for (
  let index = 0;
  index < lines.length;
  index++
) {
  const line = lines[index];
  const normalizedLine =
    normalizeSearchText(line);

  if (/^\s*#{1,6}\s+/.test(line)) {
    addWindow(index, 0, 2);
  }

  for (
    const [fieldName, aliases]
    of Object.entries(fieldAliases)
  ) {
    for (const alias of aliases) {
      const normalizedAlias =
        normalizeSearchText(alias);

      if (
        normalizedAlias &&
        (` ${normalizedLine} `).includes(
          ` ${normalizedAlias} `
        )
      ) {
        matchedFields.add(fieldName);
        matchedAliases.add(alias);
        addWindow(index);
        addCompleteTable(index);
      }
    }
  }
}

const sortedIndexes =
  [...selectedIndexes]
    .sort((a, b) => a - b);

const selectedLines = [];
let previousIndex = null;

for (const index of sortedIndexes) {
  if (
    previousIndex !== null &&
    index > previousIndex + 1
  ) {
    selectedLines.push(
      '[... ausgelassener, nicht feldrelevanter Text ...]'
    );
  }

  selectedLines.push(lines[index]);
  previousIndex = index;
}

const documentTitle =
  String(input.title ?? '').trim();

let fieldSourceText = [
  `Dokumenttitel: ${documentTitle}`,
  '',
  'Vorgefilterter KI-Dokumentinhalt:',
  '',
  selectedLines.join('\n').trim(),
]
  .join('\n')
  .trim();

let sourceTruncated = false;

if (
  fieldSourceText.length >
  MAX_SOURCE_CHARACTERS
) {
  fieldSourceText =
    fieldSourceText
      .slice(0, MAX_SOURCE_CHARACTERS)
      .replace(/\s+\S*$/, '')
      .trim();

  fieldSourceText +=
    '\n[... Vorfilter-Ausgabe wegen Größenlimit gekürzt ...]';

  sourceTruncated = true;
}

return [
  {
    json: {
      ...input,

      field_source_text:
        fieldSourceText,

      field_prefilter: {
        original_characters:
          aiContent.length,

        selected_characters:
          fieldSourceText.length,

        source_truncated:
          sourceTruncated,

        matched_fields:
          [...matchedFields],

        matched_aliases:
          [...matchedAliases],
      },
    },
  },
];

