function extractJsonObjects(text) {
  const results = [];
  let start = -1;
  let depth = 0;
  let inString = false;
  let escaped = false;

  for (
    let index = 0;
    index < text.length;
    index++
  ) {
    const char = text[index];

    if (inString) {
      if (escaped) {
        escaped = false;
        continue;
      }

      if (char === '\\') {
        escaped = true;
        continue;
      }

      if (char === '"') {
        inString = false;
      }

      continue;
    }

    if (char === '"') {
      inString = true;
      continue;
    }

    if (char === '{') {
      if (depth === 0) {
        start = index;
      }

      depth++;
      continue;
    }

    if (char === '}') {
      depth--;

      if (
        depth === 0 &&
        start >= 0
      ) {
        results.push(
          text.slice(start, index + 1)
        );
        start = -1;
      }
    }
  }

  return results;
}

function parseModelJson(value) {
  const raw =
    String(value ?? '').trim();

  const candidates = [
    ...extractJsonObjects(raw),
    raw
      .replace(/^```json\s*/i, '')
      .replace(/^```\s*/i, '')
      .replace(/\s*```$/i, '')
      .trim(),
  ];

  for (const candidate of candidates) {
    if (!candidate) {
      continue;
    }

    try {
      return {
        parsed: true,
        data: JSON.parse(candidate),
      };
    } catch {
      // Nächsten Kandidaten prüfen.
    }
  }

  return {
    parsed: false,
    data: {},
  };
}

function cleanString(value) {
  return String(value ?? '')
    .replace(/\s+/g, ' ')
    .trim();
}

function normalizeName(value) {
  return cleanString(value)
    .toLowerCase()
    .replace(/ä/g, 'ae')
    .replace(/ö/g, 'oe')
    .replace(/ü/g, 'ue')
    .replace(/ß/g, 'ss')
    .replace(/[^a-z0-9]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

const canonicalNames = new Map([
  ['betroffener', 'Betroffener'],
  ['betroffene person', 'Betroffener'],
  ['patient', 'Betroffener'],
  ['patientin', 'Betroffener'],

  ['rechnungsbetrag', 'Rechnungsbetrag'],
  ['gesamtbetrag', 'Rechnungsbetrag'],
  ['bruttobetrag', 'Rechnungsbetrag'],
  ['zahlbetrag', 'Rechnungsbetrag'],

  ['bezahlt', 'Bezahlt'],
  ['zahlungsstatus', 'Bezahlt'],

  [
    'frist wiedervorlage',
    'Frist - Wiedervorlage'
  ],
  ['frist', 'Frist - Wiedervorlage'],
  [
    'wiedervorlage',
    'Frist - Wiedervorlage'
  ],
  [
    'faelligkeitsdatum',
    'Frist - Wiedervorlage'
  ],

  ['fortbildung', 'Fortbildung'],
  ['weiterbildung', 'Fortbildung'],
  ['schulung', 'Fortbildung'],

  [
    'leistungszeitraum von',
    'Leistungszeitraum von'
  ],
  [
    'leistungsbeginn',
    'Leistungszeitraum von'
  ],

  [
    'leistungszeitraum bis',
    'Leistungszeitraum bis'
  ],
  [
    'leistungsende',
    'Leistungszeitraum bis'
  ],

  ['rechnungsnummer', 'Rechnungsnummer'],
  ['rechnung nr', 'Rechnungsnummer'],
  ['belegnummer', 'Rechnungsnummer'],
  ['invoice number', 'Rechnungsnummer'],
  ['invoice no', 'Rechnungsnummer'],
]);

const allowedFields = new Set([
  'Betroffener',
  'Rechnungsbetrag',
  'Bezahlt',
  'Frist - Wiedervorlage',
  'Fortbildung',
  'Leistungszeitraum von',
  'Leistungszeitraum bis',
  'Rechnungsnummer',
]);

const emptyWords = new Set([
  '',
  'n/a',
  'na',
  'null',
  'nicht zutreffend',
  'keine',
  'kein',
  'leer',
  'unbekannt',
  'unknown',
  'unklar',
]);

function canonicalFieldName(value) {
  const raw = cleanString(value);

  if (allowedFields.has(raw)) {
    return raw;
  }

  return (
    canonicalNames.get(
      normalizeName(raw)
    ) ?? null
  );
}

function isEmptyValue(value) {
  if (
    value === null ||
    value === undefined
  ) {
    return true;
  }

  if (typeof value === 'string') {
    return emptyWords.has(
      value.trim().toLowerCase()
    );
  }

  return false;
}

function normalizeBetroffener(value) {
  let text = cleanString(value);

  if (isEmptyValue(text)) {
    return null;
  }

  const companyWords = [
    'gmbh',
    ' ag',
    ' kg',
    ' ug',
    ' e.v.',
    'bank',
    'sparkasse',
    'versicherung',
    'ionos',
    'intensomed',
  ];

  const lowered =
    ` ${text.toLowerCase()} `;

  if (
    companyWords.some(
      word => lowered.includes(word)
    )
  ) {
    throw new Error(
      'Wert sieht wie Firma oder Organisation aus'
    );
  }

  text = text.replace(
    /^(herr|frau|patient|patientin|betroffener|betroffene)\s+/i,
    ''
  );

  if (text.includes(',')) {
    const surname =
      cleanString(text.split(',')[0]);

    return surname || null;
  }

  const parts =
    text.split(/\s+/).filter(Boolean);

  if (parts.length === 0) {
    return null;
  }

  return parts.length >= 2
    ? parts[parts.length - 1]
    : parts[0];
}

function validateDateParts(
  year,
  month,
  day
) {
  const numericYear = Number(year);
  const numericMonth = Number(month);
  const numericDay = Number(day);

  const date =
    new Date(Date.UTC(
      numericYear,
      numericMonth - 1,
      numericDay
    ));

  if (
    date.getUTCFullYear() !== numericYear ||
    date.getUTCMonth() + 1 !== numericMonth ||
    date.getUTCDate() !== numericDay
  ) {
    throw new Error('Ungültiges Datum');
  }

  return [
    String(numericYear).padStart(4, '0'),
    String(numericMonth).padStart(2, '0'),
    String(numericDay).padStart(2, '0'),
  ].join('-');
}

function normalizeShortYear(value) {
  const year = Number(value);

  if (year >= 100) {
    return year;
  }

  return year >= 69
    ? 1900 + year
    : 2000 + year;
}

function parseDateValue(
  value,
  fieldName
) {
  const text = cleanString(value);

  if (isEmptyValue(text)) {
    return null;
  }

  let match = text.match(
    /\b(\d{4})-(\d{1,2})-(\d{1,2})\b/
  );

  if (match) {
    return validateDateParts(
      match[1],
      match[2],
      match[3]
    );
  }

  match = text.match(
    /\b(\d{4})[/.](\d{1,2})[/.](\d{1,2})\b/
  );

  if (match) {
    return validateDateParts(
      match[1],
      match[2],
      match[3]
    );
  }

  match = text.match(
    /\b(\d{1,2})[./-](\d{1,2})[./-](\d{2,4})\b/
  );

  if (match) {
    return validateDateParts(
      normalizeShortYear(match[3]),
      match[2],
      match[1]
    );
  }

  const months = {
    januar: 1,
    februar: 2,
    maerz: 3,
    märz: 3,
    april: 4,
    mai: 5,
    juni: 6,
    juli: 7,
    august: 8,
    september: 9,
    oktober: 10,
    november: 11,
    dezember: 12,
  };

  match = text
    .toLowerCase()
    .match(
      /\b(januar|februar|maerz|märz|april|mai|juni|juli|august|september|oktober|november|dezember)\s+(\d{4})\b/
    );

  if (
    match &&
    (
      fieldName ===
        'Leistungszeitraum von' ||
      fieldName ===
        'Leistungszeitraum bis'
    )
  ) {
    const month = months[match[1]];
    const year = Number(match[2]);

    const day =
      fieldName ===
      'Leistungszeitraum bis'
        ? new Date(
            Date.UTC(year, month, 0)
          ).getUTCDate()
        : 1;

    return validateDateParts(
      year,
      month,
      day
    );
  }

  throw new Error(
    `Ungültiges Datum: ${text}`
  );
}

function parseBooleanValue(value) {
  if (typeof value === 'boolean') {
    return value;
  }

  const text =
    cleanString(value).toLowerCase();

  const falseValues = [
    'false',
    'nein',
    'no',
    '0',
    'nicht bezahlt',
    'unbezahlt',
    'offen',
    'fällig',
    'faellig',
    'zu bezahlen',
    'bitte überweisen',
    'bitte ueberweisen',
    'zahlung ausstehend',
  ];

  const trueValues = [
    'true',
    'ja',
    'yes',
    '1',
    'bezahlt',
    'zahlung erhalten',
    'zahlung eingegangen',
    'betrag beglichen',
    'beglichen',
    'bezahlt am',
  ];

  if (
    falseValues.some(
      entry =>
        text === entry ||
        text.includes(entry)
    )
  ) {
    return false;
  }

  if (
    trueValues.some(
      entry =>
        text === entry ||
        text.includes(entry)
    )
  ) {
    return true;
  }

  throw new Error(
    `Unklarer Boolean-Wert: ${value}`
  );
}

function parseMoneyValue(value) {
  if (
    typeof value === 'number' &&
    Number.isFinite(value)
  ) {
    return `EUR${value.toFixed(2)}`;
  }

  let text = cleanString(value)
    .replace(/€/g, '')
    .replace(/EUR/gi, '')
    .replace(/\s/g, '');

  if (isEmptyValue(text)) {
    return null;
  }

  if (
    /^-?\d{1,3}(?:\.\d{3})+(?:,\d{1,2})?$/.test(
      text
    )
  ) {
    text =
      text.replace(/\./g, '')
        .replace(',', '.');
  } else if (
    /^-?\d{1,3}(?:,\d{3})+(?:\.\d{1,2})?$/.test(
      text
    )
  ) {
    text = text.replace(/,/g, '');
  } else if (
    text.includes(',') &&
    text.includes('.')
  ) {
    if (
      text.lastIndexOf(',') >
      text.lastIndexOf('.')
    ) {
      text =
        text.replace(/\./g, '')
          .replace(',', '.');
    } else {
      text = text.replace(/,/g, '');
    }
  } else if (text.includes(',')) {
    text =
      text.replace(/\./g, '')
        .replace(',', '.');
  }

  text = text.replace(/[^0-9.-]/g, '');

  const amount = Number(text);

  if (!Number.isFinite(amount)) {
    throw new Error(
      `Ungültiger Geldbetrag: ${value}`
    );
  }

  return `EUR${amount.toFixed(2)}`;
}

function normalizeTextValue(
  value,
  fieldName
) {
  let text = cleanString(value);

  if (isEmptyValue(text)) {
    return null;
  }

  if (fieldName === 'Betroffener') {
    text = normalizeBetroffener(text);
  }

  if (!text) {
    return null;
  }

  if (text.length > 128) {
    throw new Error(
      `Textwert ist länger als 128 Zeichen`
    );
  }

  return text;
}

function normalizeFieldValue(
  fieldName,
  value
) {
  switch (fieldName) {
    case 'Betroffener':
    case 'Fortbildung':
    case 'Rechnungsnummer':
      return normalizeTextValue(
        value,
        fieldName
      );

    case 'Rechnungsbetrag':
      return parseMoneyValue(value);

    case 'Bezahlt':
      return parseBooleanValue(value);

    case 'Frist - Wiedervorlage':
    case 'Leistungszeitraum von':
    case 'Leistungszeitraum bis':
      return parseDateValue(
        value,
        fieldName
      );

    default:
      throw new Error(
        `Nicht unterstütztes Feld: ${fieldName}`
      );
  }
}

const source =
  $('Feldrelevante Textstellen vorfiltern')
    .first()
    .json;

const parsed =
  parseModelJson(
    $json.message?.content
  );

const warnings = [];
const detectedCustomFields = [];
const seenFields = new Set();

let modelItems = [];
let fieldDetectionValid = false;

if (
  parsed.parsed &&
  Array.isArray(
    parsed.data.custom_fields
  )
) {
  fieldDetectionValid = true;
  modelItems =
    parsed.data.custom_fields;
} else if (
  parsed.parsed &&
  parsed.data.custom_fields &&
  typeof parsed.data.custom_fields ===
    'object'
) {
  fieldDetectionValid = true;
  modelItems =
    Object.entries(
      parsed.data.custom_fields
    ).map(([name, value]) => ({
      name,
      value,
      evidence: '',
    }));
} else {
  warnings.push(
    'Feldantwort enthält keine gültige custom_fields-Liste.'
  );
}

for (const item of modelItems) {
  const fieldName =
    canonicalFieldName(
      item?.name ??
      item?.field ??
      item?.field_name
    );

  if (!fieldName) {
    warnings.push(
      `Unbekannter Feldname wurde ignoriert: ${cleanString(item?.name)}`
    );
    continue;
  }

  if (seenFields.has(fieldName)) {
    warnings.push(
      `Doppelter Feldwert wurde ignoriert: ${fieldName}`
    );
    continue;
  }

  const rawValue =
    item?.value ??
    item?.text ??
    item?.answer;

  if (isEmptyValue(rawValue)) {
    continue;
  }

  try {
    const normalizedValue =
      normalizeFieldValue(
        fieldName,
        rawValue
      );

    if (
      normalizedValue === null ||
      normalizedValue === undefined
    ) {
      continue;
    }

    detectedCustomFields.push({
      name:
        fieldName,

      value:
        normalizedValue,

      evidence:
        cleanString(
          item?.evidence
        ).slice(0, 300),
    });

    seenFields.add(fieldName);
  } catch (error) {
    warnings.push(
      `${fieldName}: ${error.message}`
    );
  }
}

const periodStart =
  detectedCustomFields.find(
    item =>
      item.name ===
      'Leistungszeitraum von'
  );

const periodEnd =
  detectedCustomFields.find(
    item =>
      item.name ===
      'Leistungszeitraum bis'
  );

if (
  periodStart &&
  periodEnd &&
  periodStart.value > periodEnd.value
) {
  warnings.push(
    'Leistungszeitraum wurde verworfen: Startdatum liegt nach dem Enddatum.'
  );

  for (
    let index =
      detectedCustomFields.length - 1;
    index >= 0;
    index--
  ) {
    if (
      detectedCustomFields[index].name ===
        'Leistungszeitraum von' ||
      detectedCustomFields[index].name ===
        'Leistungszeitraum bis'
    ) {
      detectedCustomFields.splice(
        index,
        1
      );
    }
  }
}

const {
  field_source_text,
  field_prefilter,
  ...productionSource
} = source;

const productionDetectedFields =
  detectedCustomFields.map(
    ({ name, value }) => ({
      name,
      value,
    })
  );

return [
  {
    json: {
      ...productionSource,

      field_detection_parsed:
        parsed.parsed,

      field_detection_valid:
        fieldDetectionValid,

      detected_custom_fields:
        productionDetectedFields,

      field_detection_warnings:
        warnings,
    },
  },
];

